29	// Parse parses the input just enough to group tokens, in
30	// order, by server block. No further parsing is performed.
31	// Server blocks are returned in the order in which they appear.
32	// Directives that do not appear in validDirectives will cause
33	// an error. If you do not want to check for valid directives,
34	// pass in nil instead.
35	//
36	// Environment variables in {$ENVIRONMENT_VARIABLE} notation
37	// are expanded after lexing, against a snapshot of the process
38	// environment taken when Parse begins; the same snapshot applies
39	// to every imported file.
40	func Parse(filename string, input []byte) ([]ServerBlock, error) {
41		// unfortunately, we must copy the input because parsing must
42		// remain a read-only operation on the caller's buffer (#4422)
43		inputCopy := make([]byte, len(input))
44		copy(inputCopy, input)
45	
46		// capture the environment once so the top-level file and all of
47		// its imports resolve variables against the same snapshot
48		env := newEnvSnapshot()
49	
50		tokens, err := allTokens(filename, inputCopy, env)
51		if err != nil {
52			return nil, err
53		}
54		p := parser{
55			Dispenser: NewDispenser(tokens),
56			env:       env,
57			importGraph: importGraph{
58				nodes: make(map[string]struct{}),
59				edges: make(adjacency),
60			},
61		}
62		return p.parseAll()
63	}
64	
65	// allTokens lexes the entire input, but does not parse it.
66	// It returns all the tokens from the input, unstructured
67	// and in order, with environment variables expanded against env.
68	func allTokens(filename string, input []byte, env envSnapshot) ([]Token, error) {
69		tokens, err := Tokenize(input, filename)
70		if err != nil {
71			return nil, err
72		}
73		return expandEnvTokens(tokens, env)
74	}
75	
76	type parser struct {
77		*Dispenser
78		block           ServerBlock // current server block being parsed
79		eof             bool        // if we encounter a valid EOF in a hard place
80		definedSnippets map[string][]Token
81		nesting         int
82		importGraph     importGraph
83		env             envSnapshot // environment shared by the top-level file and all imports
84	}
85	
86	func (p *parser) parseAll() ([]ServerBlock, error) {
87		var blocks []ServerBlock
88	
89		for p.Next() {
90			err := p.parseOne()
91			if err != nil {
92				return blocks, err
93			}
94			if len(p.block.Keys) > 0 || len(p.block.Segments) > 0 {
95				blocks = append(blocks, p.block)
96			}
97			if p.nesting > 0 {
98				return blocks, p.EOFErr()
99			}
100		}
101	
102		return blocks, nil
103	}
104	
105	func (p *parser) parseOne() error {
106		p.block = ServerBlock{}
107		return p.begin()
108	}
109	
110	func (p *parser) begin() error {
111		if len(p.tokens) == 0 {
112			return nil
113		}
114	
115		err := p.addresses()
116		if err != nil {
117			return err
118		}
119	
120		if p.eof {
121			// this happens if the Caddyfile consists of only
122			// a line of addresses and nothing else
123			return nil
124		}
125	
126		if ok, name := p.isNamedRoute(); ok {
127			// we just need a dummy leading token to ease parsing later
128			nameToken := p.Token()
129			nameToken.Text = name
130	
131			// named routes only have one key, the route name
132			p.block.Keys = []Token{nameToken}
133			p.block.IsNamedRoute = true
134	
135			// get all the tokens from the block, including the braces
136			tokens, err := p.blockTokens(true)
137			if err != nil {
138				return err
139			}
140			tokens = append([]Token{nameToken}, tokens...)
141			p.block.Segments = []Segment{tokens}
142			return nil
143		}
144	
145		if ok, name := p.isSnippet(); ok {
146			if p.definedSnippets == nil {
147				p.definedSnippets = map[string][]Token{}
148			}
149			if _, found := p.definedSnippets[name]; found {
150				return p.Errf("redeclaration of previously declared snippet %s", name)
151			}
152			// consume all tokens til matched close brace
153			tokens, err := p.blockTokens(false)
154			if err != nil {
155				return err
156			}
157			// Just as we need to track which file the token comes from, we need to
158			// keep track of which snippet the token comes from. This is helpful
159			// in tracking import cycles across files/snippets by namespacing them.
160			// Without this, we end up with false-positives in cycle-detection.
161			for k, v := range tokens {
162				v.snippetName = name
163				tokens[k] = v
164			}
165			p.definedSnippets[name] = tokens
166			// empty block keys so we don't save this block as a real server.
167			p.block.Keys = nil
168			return nil
169		}
170	
171		return p.blockContents()
172	}
173	
174	func (p *parser) addresses() error {
175		var expectingAnother bool
176	
177		for {
178			value := p.Val()
179			token := p.Token()
180	
181			// Reject request matchers if trying to define them globally
182			if strings.HasPrefix(value, "@") {
183				return p.Errf("request matchers may not be defined globally, they must be in a site block; found %s", value)
184			}
185	
186			// Special case: import directive replaces tokens during parse-time
187			if value == "import" && p.isNewLine() {
188				err := p.doImport(0)
189				if err != nil {
190					return err
191				}
192				continue
193			}
194	
195			// Open brace definitely indicates end of addresses
196			if value == "{" {
197				if expectingAnother {
198					return p.Errf("Expected another address but had '%s' - check for extra comma", value)
199				}
200				// Mark this server block as being defined with braces.
201				// This is used to provide a better error message when
202				// the user may have tried to define two server blocks
203				// without having used braces, which are required in
204				// that case.
205				p.block.HasBraces = true
206				break
207			}
208	
209			// Users commonly forget to place a space between the address and the '{'
210			if strings.HasSuffix(value, "{") {
211				return p.Errf("Site addresses cannot end with a curly brace: '%s' - put a space between the token and the brace", value)
212			}
213	
214			if value != "" { // empty token possible if user typed ""
215				// Trailing comma indicates another address will follow, which
216				// may possibly be on the next line
217				if value[len(value)-1] == ',' {
218					value = value[:len(value)-1]
219					expectingAnother = true
220				} else {
221					expectingAnother = false // but we may still see another one on this line
222				}
223	
224				// If there's a comma here, it's probably because they didn't use a space
225				// between their two domains, e.g. "foo.com,bar.com", which would not be
226				// parsed as two separate site addresses.
227				if strings.Contains(value, ",") {
228					return p.Errf("Site addresses cannot contain a comma ',': '%s' - put a space after the comma to separate site addresses", value)
229				}
230	
231				// After the above, a comma surrounded by spaces would result
232				// in an empty token which we should ignore
233				if value != "" {
234					// Add the token as a site address
235					token.Text = value
236					p.block.Keys = append(p.block.Keys, token)
237				}
238			}
239	
240			// Advance token and possibly break out of loop or return error
241			hasNext := p.Next()
242			if expectingAnother && !hasNext {
243				return p.EOFErr()
244			}
245			if !hasNext {
246				p.eof = true
247				break // EOF
248			}
249			if !expectingAnother && p.isNewLine() {
250				break
251			}
252		}
253	
254		return nil
255	}
256	
257	func (p *parser) blockContents() error {
258		errOpenCurlyBrace := p.openCurlyBrace()
259		if errOpenCurlyBrace != nil {
260			// single-server configs don't need curly braces
261			p.cursor--
262		}
263	
264		err := p.directives()
265		if err != nil {
266			return err
267		}
268	
269		// only look for close curly brace if there was an opening
270		if errOpenCurlyBrace == nil {
271			err = p.closeCurlyBrace()
272			if err != nil {
273				return err
274			}
275		}
276	
277		return nil
278	}
279	
280	// directives parses through all the lines for directives
281	// and it expects the next token to be the first
282	// directive. It goes until EOF or closing curly brace
283	// which ends the server block.
284	func (p *parser) directives() error {
285		for p.Next() {
286			// end of server block
287			if p.Val() == "}" {
288				// p.nesting has already been decremented
289				break
290			}
291	
292			// special case: import directive replaces tokens during parse-time
293			if p.Val() == "import" {
294				err := p.doImport(1)
295				if err != nil {
296					return err
297				}
298				p.cursor-- // cursor is advanced when we continue, so roll back one more
299				continue
300			}
301	
302			// normal case: parse a directive as a new segment
303			// (a "segment" is a line which starts with a directive
304			// and which ends at the end of the line or at the end of
305			// the block that is opened at the end of the line)
306			if err := p.directive(); err != nil {
307				return err
308			}
309		}
310	
311		return nil
312	}
313	
314	// doImport swaps out the import directive and its argument
315	// (a total of 2 tokens) with the tokens in the specified file
316	// or globbing pattern. When the function returns, the cursor
317	// is on the token before where the import directive was. In
318	// other words, call Next() to access the first token that was
319	// imported.
320	func (p *parser) doImport(nesting int) error {
321		// syntax checks
322		if !p.NextArg() {
323			return p.ArgErr()
324		}
325		importPattern := p.Val()
326		if importPattern == "" {
327			return p.Err("Import requires a non-empty filepath")
328		}
329	
330		// grab remaining args as placeholder replacements
331		args := p.RemainingArgs()
332	
333		// set up a replacer for non-variadic args replacement
334		repl := makeArgsReplacer(args)
335	
336		// grab all the tokens (if it exists) from within a block that follows the import
337		var blockTokens []Token
338		for currentNesting := p.Nesting(); p.NextBlock(currentNesting); {
339			blockTokens = append(blockTokens, p.Token())
340		}
341		// initialize with size 1
342		blockMapping := make(map[string][]Token, 1)
343		if len(blockTokens) > 0 {
344			// use such tokens to create a new dispenser, and then use it to parse each block
345			bd := NewDispenser(blockTokens)
346	
347			// one iteration processes one sub-block inside the import
348			for bd.Next() {
349				currentMappingKey := bd.Val()
350	
351				if currentMappingKey == "{" {
352					return p.Err("anonymous blocks are not supported")
353				}
354	
355				// load up all arguments (if there even are any)
356				currentMappingTokens := bd.RemainingArgsAsTokens()
357	
358				// load up the entire block
359				for mappingNesting := bd.Nesting(); bd.NextBlock(mappingNesting); {
360					currentMappingTokens = append(currentMappingTokens, bd.Token())
361				}
362	
363				blockMapping[currentMappingKey] = currentMappingTokens
364			}
365		}
366	
367		// splice out the import directive and its arguments
368		// (2 tokens, plus the length of args)
369		tokensBefore := p.tokens[:p.cursor-1-len(args)-len(blockTokens)]
370		tokensAfter := p.tokens[p.cursor+1:]
371		var importedTokens []Token
372		var nodes []string
373	
374		// first check snippets. That is a simple, non-recursive replacement
375		if p.definedSnippets != nil && p.definedSnippets[importPattern] != nil {
376			importedTokens = p.definedSnippets[importPattern]
377			if len(importedTokens) > 0 {
378				// just grab the first one
379				nodes = append(nodes, fmt.Sprintf("%s:%s", importedTokens[0].File, importedTokens[0].snippetName))
380			}
381		} else {
382			// make path relative to the file of the _token_ being processed rather
383			// than current working directory (issue #867) and then use glob to get
384			// list of matching filenames
385			absFile, err := caddy.FastAbs(p.Dispenser.File())
386			if err != nil {
387				return p.Errf("Failed to get absolute path of file: %s: %v", p.Dispenser.File(), err)
388			}
389	
390			var matches []string
391			var globPattern string
392			if !filepath.IsAbs(importPattern) {
393				globPattern = filepath.Join(filepath.Dir(absFile), importPattern)
394			} else {
395				globPattern = importPattern
396			}
397			if strings.Count(globPattern, "*") > 1 || strings.Count(globPattern, "?") > 1 ||
398				(strings.Contains(globPattern, "[") && strings.Contains(globPattern, "]")) {
399				// See issue #2096 - a pattern with many glob expansions can hang for too long
400				return p.Errf("Glob pattern may only contain one wildcard (*), but has others: %s", globPattern)
401			}
402			matches, err = filepath.Glob(globPattern)
403			if err != nil {
404				return p.Errf("Failed to use import pattern %s: %v", importPattern, err)
405			}
406			if len(matches) == 0 {
407				if strings.ContainsAny(globPattern, "*?[]") {
408					caddy.Log().Warn("No files matching import glob pattern", zap.String("pattern", importPattern))
409				} else {
410					return p.Errf("File to import not found: %s", importPattern)
411				}
412			} else {
413				// See issue #5295 - should skip any files that start with a . when iterating over them.
414				sep := string(filepath.Separator)
415				segGlobPattern := strings.Split(globPattern, sep)
416				if strings.HasPrefix(segGlobPattern[len(segGlobPattern)-1], "*") {
417					var tmpMatches []string
418					for _, m := range matches {
419						seg := strings.Split(m, sep)
420						if !strings.HasPrefix(seg[len(seg)-1], ".") {
421							tmpMatches = append(tmpMatches, m)
422						}
423					}
424					matches = tmpMatches
425				}
426			}
427	
428			// collect all the imported tokens
429			for _, importFile := range matches {
430				newTokens, err := p.doSingleImport(importFile)
431				if err != nil {
432					return err
433				}
434				importedTokens = append(importedTokens, newTokens...)
435			}
436			nodes = matches
437		}
438	
439		nodeName := p.File()
440		if p.Token().snippetName != "" {
441			nodeName += fmt.Sprintf(":%s", p.Token().snippetName)
442		}
443		p.importGraph.addNode(nodeName)
444		p.importGraph.addNodes(nodes)
445		if err := p.importGraph.addEdges(nodeName, nodes); err != nil {
446			p.importGraph.removeNodes(nodes)
447			return err
448		}
449	
450		// copy the tokens so we don't overwrite p.definedSnippets
451		tokensCopy := make([]Token, 0, len(importedTokens))
452	
453		var (
454			maybeSnippet   bool
455			maybeSnippetId bool
456			index          int
457		)
458	
459		// run the argument replacer on the tokens
460		// golang for range slice return a copy of value
461		// similarly, append also copy value
462		for i, token := range importedTokens {
463			// update the token's imports to refer to import directive filename, line number and snippet name if there is one
464			if token.snippetName != "" {
465				token.imports = append(token.imports, fmt.Sprintf("%s:%d (import %s)", p.File(), p.Line(), token.snippetName))
466			} else {
467				token.imports = append(token.imports, fmt.Sprintf("%s:%d (import)", p.File(), p.Line()))
468			}
469	
470			// naive way of determine snippets, as snippets definition can only follow name + block
471			// format, won't check for nesting correctness or any other error, that's what parser does.
472			if !maybeSnippet && nesting == 0 {
473				// first of the line
474				if i == 0 || isNextOnNewLine(tokensCopy[len(tokensCopy)-1], token) {
475					index = 0
476				} else {
477					index++
478				}
479	
480				if index == 0 && len(token.Text) >= 3 && strings.HasPrefix(token.Text, "(") && strings.HasSuffix(token.Text, ")") {
481					maybeSnippetId = true
482				}
483			}
484	
485			switch token.Text {
486			case "{":
487				nesting++
488				if index == 1 && maybeSnippetId && nesting == 1 {
489					maybeSnippet = true
490					maybeSnippetId = false
491				}
492			case "}":
493				nesting--
494				if nesting == 0 && maybeSnippet {
495					maybeSnippet = false
496				}
497			}
498			// if it is {block}, we substitute with all tokens in the block
499			// if it is {blocks.*}, we substitute with the tokens in the mapping for the *
500			var tokensToAdd []Token
501			foundBlockDirective := false
502			switch {
503			case token.Text == "{block}":
504				foundBlockDirective = true
505				tokensToAdd = blockTokens
506			case strings.HasPrefix(token.Text, "{blocks.") && strings.HasSuffix(token.Text, "}"):
507				foundBlockDirective = true
508				// {blocks.foo.bar} will be extracted to key `foo.bar`
509				blockKey := strings.TrimPrefix(strings.TrimSuffix(token.Text, "}"), "{blocks.")
510				val, ok := blockMapping[blockKey]
511				if ok {
512					tokensToAdd = val
513				}
514			}
515	
516			if foundBlockDirective {
517				if maybeSnippet {
518					tokensCopy = append(tokensCopy, token)
519				} else {
520					tokensCopy = append(tokensCopy, tokensToAdd...)
521				}
522				continue
523			}
524	
525			if maybeSnippet {
526				tokensCopy = append(tokensCopy, token)
527				continue
528			}
529	
530			foundVariadic, startIndex, endIndex := parseVariadic(token, len(args))
531			if foundVariadic {
532				for _, arg := range args[startIndex:endIndex] {
533					token.Text = arg
534					tokensCopy = append(tokensCopy, token)
535				}
536			} else {
537				token.Text = repl.ReplaceKnown(token.Text, "")
538				tokensCopy = append(tokensCopy, token)
539			}
540		}
541	
542		// splice the imported tokens in the place of the import statement
543		// and rewind cursor so Next() will land on first imported token
544		p.tokens = append(tokensBefore, append(tokensCopy, tokensAfter...)...)
545		p.cursor -= len(args) + len(blockTokens) + 1
546	
547		return nil
548	}
549	
550	// doSingleImport lexes the individual file at importFile and returns
551	// its tokens or an error, if any.
552	func (p *parser) doSingleImport(importFile string) ([]Token, error) {
553		file, err := os.Open(importFile)
554		if err != nil {
555			return nil, p.Errf("Could not import %s: %v", importFile, err)
556		}
557		defer file.Close()
558	
559		if info, err := file.Stat(); err != nil {
560			return nil, p.Errf("Could not import %s: %v", importFile, err)
561		} else if info.IsDir() {
562			return nil, p.Errf("Could not import %s: is a directory", importFile)
563		}
564	
565		input, err := io.ReadAll(file)
566		if err != nil {
567			return nil, p.Errf("Could not read imported file %s: %v", importFile, err)
568		}
569	
570		// only warning in case of empty files
571		if len(input) == 0 || len(strings.TrimSpace(string(input))) == 0 {
572			caddy.Log().Warn("Import file is empty", zap.String("file", importFile))
573			return []Token{}, nil
574		}
575	
576		importedTokens, err := allTokens(importFile, input, p.env)
577		if err != nil {
578			return nil, p.Errf("Could not read tokens while importing %s: %v", importFile, err)
579		}
580	
581		// Tack the file path onto these tokens so errors show the imported file's name
582		// (we use full, absolute path to avoid bugs: issue #1892)
583		filename, err := caddy.FastAbs(importFile)
584		if err != nil {
585			return nil, p.Errf("Failed to get absolute path of file: %s: %v", importFile, err)
586		}
587		for i := range importedTokens {
588			importedTokens[i].File = filename
589		}
590	
591		return importedTokens, nil
592	}
593	
594	// directive collects tokens until the directive's scope
595	// closes (either end of line or end of curly brace block).
596	// It expects the currently-loaded token to be a directive
597	// (or } that ends a server block). The collected tokens
598	// are loaded into the current server block for later use
599	// by directive setup functions.
600	func (p *parser) directive() error {
601		// a segment is a list of tokens associated with this directive
602		var segment Segment
603	
604		// the directive itself is appended as a relevant token
605		segment = append(segment, p.Token())
606	
607		for p.Next() {
608			if p.Val() == "{" {
609				p.nesting++
610				if !p.isNextOnNewLine() && p.Token().wasQuoted == 0 {
611					return p.Err("Unexpected next token after '{' on same line")
612				}
613				if p.isNewLine() {
614					return p.Err("Unexpected '{' on a new line; did you mean to place the '{' on the previous line?")
615				}
616			} else if p.Val() == "{}" {
617				if p.isNextOnNewLine() && p.Token().wasQuoted == 0 {
618					return p.Err("Unexpected '{}' at end of line")
619				}
620			} else if p.isNewLine() && p.nesting == 0 {
621				p.cursor-- // read too far
622				break
623			} else if p.Val() == "}" && p.nesting > 0 {
624				p.nesting--
625			} else if p.Val() == "}" && p.nesting == 0 {
626				return p.Err("Unexpected '}' because no matching opening brace")
627			} else if p.Val() == "import" && p.isNewLine() {
628				if err := p.doImport(1); err != nil {
629					return err
630				}
631				p.cursor-- // cursor is advanced when we continue, so roll back one more
632				continue
633			}
634	
635			segment = append(segment, p.Token())
636		}
637	
638		p.block.Segments = append(p.block.Segments, segment)
639	
640		if p.nesting > 0 {
641			return p.EOFErr()
642		}
643	
644		return nil
645	}
646	
647	// openCurlyBrace expects the current token to be an
648	// opening curly brace. This acts like an assertion
649	// because it returns an error if the token is not
650	// an opening curly brace. It does NOT advance the token.
651	func (p *parser) openCurlyBrace() error {
652		if p.Val() != "{" {
653			if p.valLooksLikeGlobalOptionsAfterImportedSnippets() {
654				return p.Err("global options block must appear before import directives; move the global options block to the top of the Caddyfile")
655			}
656			return p.SyntaxErr("{")
657		}
658		return nil
659	}
660	
661	func (p *parser) valLooksLikeGlobalOptionsAfterImportedSnippets() bool {
662		if p.Val() != "import" || len(p.block.Keys) == 0 {
663			return false
664		}
665	
666		for _, key := range p.block.Keys {
667			if !strings.HasPrefix(key.Text, "(") || !strings.HasSuffix(key.Text, ")") {
668				return false
669			}
670		}
671	
672		return true
673	}
674	
675	// closeCurlyBrace expects the current token to be
676	// a closing curly brace. This acts like an assertion
677	// because it returns an error if the token is not
678	// a closing curly brace. It does NOT advance the token.
679	func (p *parser) closeCurlyBrace() error {
680		if p.Val() != "}" {
681			return p.SyntaxErr("}")
682		}
683		return nil
684	}
685	
686	func (p *parser) isNamedRoute() (bool, string) {
687		keys := p.block.Keys
688		// A named route block is a single key with parens, prefixed with &.
689		if len(keys) == 1 && strings.HasPrefix(keys[0].Text, "&(") && strings.HasSuffix(keys[0].Text, ")") {
690			return true, strings.TrimSuffix(keys[0].Text[2:], ")")
691		}
692		return false, ""
693	}
694	
695	func (p *parser) isSnippet() (bool, string) {
696		keys := p.block.Keys
697		// A snippet block is a single key with parens. Nothing else qualifies.
698		if len(keys) == 1 && strings.HasPrefix(keys[0].Text, "(") && strings.HasSuffix(keys[0].Text, ")") {
699			return true, strings.TrimSuffix(keys[0].Text[1:], ")")
700		}
701		return false, ""
702	}
703	
704	// read and store everything in a block for later replay.
705	func (p *parser) blockTokens(retainCurlies bool) ([]Token, error) {
706		// block must have curlies.
707		err := p.openCurlyBrace()
708		if err != nil {
709			return nil, err
710		}
711		nesting := 1 // count our own nesting
712		tokens := []Token{}
713		if retainCurlies {
714			tokens = append(tokens, p.Token())
715		}
716		for p.Next() {
717			if p.Val() == "}" {
718				nesting--
719				if nesting == 0 {
720					if retainCurlies {
721						tokens = append(tokens, p.Token())
722					}
723					break
724				}
725			}
726			if p.Val() == "{" {
727				nesting++
728			}
729			tokens = append(tokens, p.tokens[p.cursor])
730		}
731		// make sure we're matched up
732		if nesting != 0 {
733			return nil, p.SyntaxErr("}")
734		}
735		return tokens, nil
736	}
737	
738	// ServerBlock associates any number of keys from the
739	// head of the server block with tokens, which are
740	// grouped by segments.
741	type ServerBlock struct {
742		HasBraces    bool
743		Keys         []Token
744		Segments     []Segment
745		IsNamedRoute bool
746	}
747	
748	func (sb ServerBlock) GetKeysText() []string {
749		res := make([]string, 0, len(sb.Keys))
750		for _, k := range sb.Keys {
751			res = append(res, k.Text)
752		}
753		return res
754	}
755	
756	// DispenseDirective returns a dispenser that contains
757	// all the tokens in the server block.
758	func (sb ServerBlock) DispenseDirective(dir string) *Dispenser {
759		var tokens []Token
760		for _, seg := range sb.Segments {
761			if len(seg) > 0 && seg[0].Text == dir {
762				tokens = append(tokens, seg...)
763			}
764		}
765		return NewDispenser(tokens)
766	}
767	
768	// Segment is a list of tokens which begins with a directive
769	// and ends at the end of the directive (either at the end of
770	// the line, or at the end of a block it opens).
771	type Segment []Token
772	
773	// Directive returns the directive name for the segment.
774	// The directive name is the text of the first token.
775	func (s Segment) Directive() string {
776		if len(s) > 0 {
777			return s[0].Text
778		}
779		return ""
780	}
