// capability the readers value exposes. An open-only reader cannot be
// enumerated, so a pattern has no matches there.
func globWithReader(readers FileReaders, pattern string) ([]string, error) {
	switch r := readers.(type) {
	case interface{ Glob(string) ([]string, error) }:
		return r.Glob(pattern)
	case fs.GlobFS:
		return r.Glob(pattern)
	case fs.ReadDirFS:
		// fs.Glob walks directories itself, which works for any fs.FS
		// that can list directories.
		return fs.Glob(readerFS{r}, pattern)
	}
	return nil, nil
}

// readerFS adapts FileReaders to fs.FS for callers (fs.Glob) that want
// the interface type rather than the method set.
type readerFS struct {
	FileReaders
}

