28	)
29	
30	// readersFor builds a FileReaderFunc over an in-memory file set.
31	func readersFor(files map[string]string) FileReaderFunc {
32		return func(name string) (io.ReadCloser, error) {
33			contents, ok := files[normalizeImportPath(name)]
34			if !ok {
35				return nil, &fsPathError{op: "open", name: name, err: errNotExist}
36			}
37			return io.NopCloser(strings.NewReader(contents)), nil
38		}
39	}
40	
41	var errNotExist = errors.New("file does not exist")
42	
43	type fsPathError struct {
44		op, name string
45		err      error
46	}
47	
48	func (e *fsPathError) Error() string { return e.op + " " + e.name + ": " + e.err.Error() }
49	func (e *fsPathError) Unwrap() error { return e.err }
50	
51	// flattenBlocks renders parsed blocks as a sequence of token-text
52	// lines: directive order and exact argument bytes are the observation
53	// surface these tests rely on.
54	func flattenBlocks(blocks []ServerBlock) [][]string {
55		var out [][]string
56		for _, b := range blocks {
57			for _, seg := range b.Segments {
58				var line []string
59				for _, tok := range seg {
60					line = append(line, tok.Text)
61				}
62				out = append(out, line)
63			}
64		}
65		return out
66	}
67	
68	func assertLines(t *testing.T, want, got [][]string) {
69		t.Helper()
70		if len(got) != len(want) {
71			t.Fatalf("expected %d directive lines, got %d: %v", len(want), len(got), got)
72		}
73		for i := range want {
74			if len(got[i]) != len(want[i]) {
75				t.Fatalf("line %d: expected %v, got %v", i, want[i], got[i])
76			}
77			for j := range want[i] {
78				if got[i][j] != want[i][j] {
79					t.Fatalf("line %d, arg %d: expected %q, got %q", i, j, want[i][j], got[i][j])
80				}
81			}
82		}
83	}
84	
85	func parseWithReaders(t *testing.T, files map[string]string) ([][]string, error) {
86		t.Helper()
87		readers := readersFor(files)
88		blocks, err := Parse("Caddyfile", []byte(files["Caddyfile"]), readers)
89		if err != nil {
90			return nil, err
91		}
92		return flattenBlocks(blocks), nil
93	}
94	
95	func TestParseReadersBasicImport(t *testing.T) {
96		lines, err := parseWithReaders(t, map[string]string{
97			"Caddyfile":      ":8080 {\n\timport sub/site.caddy\n}\n",
98			"sub/site.caddy": "respond \"hello world\"\nredir /foo /bar\n",
99		})
100		if err != nil {
101			t.Fatalf("unexpected error: %v", err)
102		}
103		assertLines(t, [][]string{
104			{"respond", "hello world"},
105			{"redir", "/foo", "/bar"},
106		}, lines)
107	}
108	
109	func TestParseReadersRelativeImportIndependentOfWorkingDir(t *testing.T) {
110		lines, err := parseWithReaders(t, map[string]string{
111			"Caddyfile": ":8080 {\n\timport a/f.caddy\n}\n",
112			"a/f.caddy": "import g.caddy\n",
113			"a/g.caddy": "directive-a value\n",
114		})
115		if err != nil {
116			t.Fatalf("unexpected error: %v", err)
117		}
118		assertLines(t, [][]string{{"directive-a", "value"}}, lines)
119	}
120	
121	func TestParseReadersNormalizesSeparatorsAndDotSegments(t *testing.T) {
122		lines, err := parseWithReaders(t, map[string]string{
123			"Caddyfile":   ":8080 {\n\timport a/../sub/./f.caddy\n}\n",
124			"sub/f.caddy": "directive-norm value\n",
125		})
126		if err != nil {
127			t.Fatalf("unexpected error: %v", err)
128		}
129		assertLines(t, [][]string{{"directive-norm", "value"}}, lines)
130	
131		// backslashes resolve identically
132		lines, err = parseWithReaders(t, map[string]string{
133			"Caddyfile":   ":8080 {\n\timport sub\\f.caddy\n}\n",
134			"sub/f.caddy": "directive-sep value\n",
135		})
136		if err != nil {
137			t.Fatalf("unexpected error: %v", err)
138		}
139		assertLines(t, [][]string{{"directive-sep", "value"}}, lines)
140	}
141	
142	func TestParseReadersPreserveSpacesQuotesAndEmpty(t *testing.T) {
143		files := map[string]string{
144			"Caddyfile": ":8080 {\n" +
145				"\timport f.caddy \"hello world\" \"\" `back tick`\n" +
146				"}\n",
147			"f.caddy": "a {args[0]}\nb {args[1]}\nc {args[2]}\n",
148		}
149		blocks, err := Parse("Caddyfile", []byte(files["Caddyfile"]), readersFor(files))
150		if err != nil {
151			t.Fatalf("unexpected error: %v", err)
152		}
153		assertLines(t, [][]string{
154			{"a", "hello world"},
155			{"b", ""},
156			{"c", "back tick"},
157		}, flattenBlocks(blocks))
158	
159		// quoting provenance travels with the substituted argument
160		if !blocks[0].Segments[0][1].Quoted() {
161			t.Errorf("expected space-bearing argument to retain its quotes")
162		}
163	}
164	
165	func TestParseReadersAdjacentTextPlainAndEscapedBraces(t *testing.T) {
166		lines, err := parseWithReaders(t, map[string]string{
167			"Caddyfile": ":8080 {\n\timport f.caddy VALUE\n}\n",
168			"f.caddy": "join pre-{args[0]}-post\n" +
169				"json {\"k\":\"{args[0]}\"}\n" +
170				"plain {host} {remote} {{}}\n" +
171				"escaped \\{args[0]\\}\n",
172		})
173		if err != nil {
174			t.Fatalf("unexpected error: %v", err)
175		}
176		assertLines(t, [][]string{
177			{"join", "pre-VALUE-post"},
178			{"json", `{"k":"VALUE"}`},
179			{"plain", "{host}", "{remote}", "{{}}"},
180			{"escaped", `{args[0]}`},
181		}, lines)
